var ui_UIManager = function(input,initialGfx,hasSave,parent,mp) {
	this.hasActiveSave = false;
	this.isOpenedFromPause = false;
	this.currentState = ui_components_UIState.Splash;
	var _gthis = this;
	h2d_Object.call(this,parent);
	this.set_visible(false);
	this.inputRef = input;
	this.gfxSettings = initialGfx;
	this.hasActiveSave = hasSave;
	this.builder = new ui_UIBuilder(input,initialGfx,hasSave,this,mp);
	this.builder.splashView.onEnter = function() {
		_gthis.showMainMenu();
	};
	this.builder.mainMenuView.onActionSelected = function(act) {
		_gthis.triggerMainAction(act);
	};
	this.builder.mainMenuView.onSelectionChanged = function() {
		_gthis.layout();
	};
	this.builder.mapSelectView.onMapSelected = function(act) {
		if(_gthis.onMenuAction != null) {
			_gthis.onMenuAction(act);
		}
	};
	this.builder.mapSelectView.onBack = function() {
		_gthis.showMainMenu();
	};
	this.builder.mapSelectView.onSelectionChanged = function() {
		_gthis.layout();
	};
	this.builder.multiplayerMenuView.onHostSelected = function() {
		if(mp != null) {
			mp.hostRoom(null,"HOST");
		}
		_gthis.showMultiplayerLobby();
	};
	this.builder.multiplayerMenuView.onJoinSelected = function(code) {
		if(mp != null) {
			mp.joinRoom(code,"GUEST");
		}
		_gthis.showMultiplayerLobby();
	};
	this.builder.multiplayerMenuView.onBack = function() {
		_gthis.showMainMenu();
	};
	this.builder.multiplayerMenuView.onSelectionChanged = function() {
		_gthis.layout();
	};
	this.builder.multiplayerLobbyView.onBack = function() {
		if(mp != null) {
			mp.leaveRoom();
		}
		_gthis.showMultiplayerMenu();
	};
	this.builder.multiplayerLobbyView.onVisualRefresh = function() {
		_gthis.layout();
	};
	this.builder.pauseMenuView.onResume = function() {
		if(_gthis.onMenuAction != null) {
			_gthis.onMenuAction(ui_components_MenuAction.ResumeGame);
		}
	};
	this.builder.pauseMenuView.onRestart = function() {
		if(_gthis.onMenuAction != null) {
			_gthis.onMenuAction(ui_components_MenuAction.RestartRace);
		}
	};
	this.builder.pauseMenuView.onOptions = function() {
		_gthis.openOptions(true);
	};
	this.builder.pauseMenuView.onQuitToTitle = function() {
		if(_gthis.onMenuAction != null) {
			_gthis.onMenuAction(ui_components_MenuAction.QuitToTitle);
		}
	};
	this.builder.pauseMenuView.onSelectionChanged = function() {
		_gthis.layout();
	};
	this.builder.optionsView.onBack = function() {
		if(_gthis.isOpenedFromPause) {
			_gthis.showPause();
		} else {
			_gthis.showMainMenu();
		}
	};
	this.builder.optionsView.onTabChanged = function() {
		if(_gthis.currentState == ui_components_UIState.OptionsMenu) {
			_gthis.layout();
		}
	};
	this.builder.optionsView.gfxPanel.onUIResolutionChanged = function() {
		_gthis.layout();
	};
	this.builder.creditsView.onBack = function() {
		_gthis.showMainMenu();
	};
	this.builder.optionsView.controlsPanel.onTouchSettingsChanged = function() {
		_gthis.builder.touchControlsHUD.refreshSettings();
	};
	this.builder.touchControlsHUD.onPauseTriggered = function() {
		if(_gthis.currentState == ui_components_UIState.InGameHUD) {
			if(_gthis.onPauseRequested != null) {
				_gthis.onPauseRequested();
			} else {
				_gthis.showPause();
			}
		}
	};
};
